"""A boss launch that the monthly status read ends still reaches the pursuit list.

ch9 2026-11-17 (local driver, main line): リースリング left イデ！ for the boss at
tick 23868 as ``launched_unconfirmed`` (``target`` None, ``planned_target`` the
boss). The monthly status read saw him camped at tick 24091; the march record
ended at 24100 and wrote him back into the イデ！ garrison. ``track`` read only
``target`` and dropped anything in a garrison, so ``boss_wave_generals`` stayed
empty and no pursuit started in 1446 s. Replayed through the real expiry.
"""
from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.flows import boss_pursuit as bp
from docich.hanjuku_speedrun.hanjuku.state.regions import world as _world
from docich.hanjuku_speedrun.hanjuku.strategy import orders

BOSS = chart.boss_castle(9)
GENERAL = 'リースリング'


def launched(mem, **extra):
    record = {'general': GENERAL, 'source': 'イデ！', 'target': None, 'planned_target': BOSS,
              'status': 'launched_unconfirmed', 'tick': 23868}
    record.update(extra)
    _world(mem).setdefault('sorties', {})['A:step'] = record
    _world(mem).setdefault('garrison', {})['イデ！'] = ['どうし']


def memory(location, tick=24091):
    row = {'location': location, 'location_observed': True, 'tick': tick}
    return {'chapter': 9, 'tick': 24100, 'general_statuses': {'statuses': {GENERAL: row}}}


def test_an_unconfirmed_boss_launch_joins_the_list():
    mem = memory('camp')
    launched(mem)
    assert GENERAL in bp.track(mem)
    assert mem[bp.LIST_KEY][GENERAL]['launched'] == 23868


def test_a_camp_reading_that_ends_the_record_keeps_the_general_listed():
    mem = memory('camp')
    launched(mem)
    bp.track(mem)
    orders._expire_spent_sorties(mem)
    assert 'A:step' not in _world(mem)['sorties']
    assert GENERAL in _world(mem)['garrison']['イデ！']      # the write-back that used to drop him
    assert GENERAL in bp.track(mem)


def test_a_castle_reading_still_drops_him():
    mem = memory('castle')
    launched(mem)
    bp.track(mem)
    orders._expire_spent_sorties(mem)
    assert GENERAL not in bp.track(mem)


def test_a_camp_reading_older_than_the_launch_does_not_keep_him():
    mem = memory('camp', tick=23000)
    launched(mem)
    mem[bp.LIST_KEY] = {GENERAL: {'step': 'A:step', 'launched': 23868}}
    _world(mem)['sorties'] = {}
    _world(mem)['garrison']['イデ！'] = ['どうし', GENERAL]
    assert GENERAL not in bp.track(mem)


def test_a_lost_general_is_dropped_even_while_camped():
    mem = memory('camp')
    launched(mem)
    mem['generals_lost'] = [GENERAL]
    assert GENERAL not in bp.track(mem)
